#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("NOOP\n");
        return 0;
    }

    char *endptr;
    long size = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1]) {
        printf("ERR\n");
        return 0;
    }

    long *heap = (long *) malloc(size * sizeof(long));
    if (heap == NULL) {
        printf("FULL\n");
        return 0;
    }

    for (int i = 0; i < size; i++) {
        heap[i] = 0;
    }

    for (int i = 2; i < argc; i++) {
        long value = strtol(argv[i], &endptr, 10);
        if (endptr == argv[i]) {
            printf("ERR\n");
            free(heap);
            return 0;
        }
        for (int j = 0; j < size; j++) {
            if (heap[j] == 0) {
                heap[j] = value;
                printf("INS %ld\n", value);
                break;
            }
        }
    }

    printf("MIN %ld\n", heap[0]);
    free(heap);
    return 0;
}
